import { describe, expect, it } from 'vitest';
import { Add, Circle, GeometryEntity, Line2D, Matrix, Mul, Point2D, Pow, RegularPolygon, Segment2D, Sym, Triangle, add, isUnsolved, mul, pi, pow, rational, subs, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.geometry.entity", () => {
  it("t2.encloses(t)", () => {
    expect(sympyStr(Triangle(Point2D(rational(2), rational(0), { evaluate: false }), Point2D(rational(-1), pow(3, rational(1, 2)), { evaluate: false }), Point2D(rational(-1), mul(-1, pow(3, rational(1, 2))), { evaluate: false })).encloses(Triangle(Point2D(rational(1), rational(0), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(1, 2), pow(3, rational(1, 2))), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(-1, 2), pow(3, rational(1, 2))), { evaluate: false }))))).toBe('True');
  });
  it("t.encloses(t2)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  // the arguments do not type-check against the public API
  //   Line(a, b).parameter_value((1, 1), t)
  //   => {t: 1/2}
  it.todo("Line(a, b).parameter_value((1, 1), t)");
  it("t.rotate(pi/2) # vertex on y axis now", () => {
    expect(sympyStr(Triangle(Point2D(rational(1), rational(0), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(1, 2), pow(3, rational(1, 2))), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(-1, 2), pow(3, rational(1, 2))), { evaluate: false })).rotate(mul(rational(1, 2), pi)))).toBe('Triangle(Point2D(0, 1), Point2D(-sqrt(3)/2, -1/2), Point2D(sqrt(3)/2, -1/2))');
  });
  it("t.scale(2)", () => {
    expect(sympyStr(Triangle(Point2D(rational(1), rational(0), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(1, 2), pow(3, rational(1, 2))), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(-1, 2), pow(3, rational(1, 2))), { evaluate: false })).scale(2))).toBe('Triangle(Point2D(2, 0), Point2D(-1, sqrt(3)/2), Point2D(-1, -sqrt(3)/2))');
  });
  it("t.scale(2, 2)", () => {
    expect(sympyStr(Triangle(Point2D(rational(1), rational(0), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(1, 2), pow(3, rational(1, 2))), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(-1, 2), pow(3, rational(1, 2))), { evaluate: false })).scale(2, 2))).toBe('Triangle(Point2D(2, 0), Point2D(-1, sqrt(3)), Point2D(-1, -sqrt(3)))');
  });
  it("t.translate(2)", () => {
    expect(sympyStr(Triangle(Point2D(rational(1), rational(0), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(1, 2), pow(3, rational(1, 2))), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(-1, 2), pow(3, rational(1, 2))), { evaluate: false })).translate(2))).toBe('Triangle(Point2D(3, 0), Point2D(3/2, sqrt(3)/2), Point2D(3/2, -sqrt(3)/2))');
  });
  it("t.translate(2, 2)", () => {
    expect(sympyStr(Triangle(Point2D(rational(1), rational(0), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(1, 2), pow(3, rational(1, 2))), { evaluate: false }), Point2D(rational(-1, 2), mul(rational(-1, 2), pow(3, rational(1, 2))), { evaluate: false })).translate(2, 2))).toBe('Triangle(Point2D(3, 2), Point2D(3/2, sqrt(3)/2 + 2), Point2D(3/2, 2 - sqrt(3)/2))');
  });
  it("Point(1, 1).transform(rot_about_11)", () => {
    expect(sympyStr(Point2D(rational(1), rational(1), { evaluate: false }).transform(Matrix.of([[rational(0), rational(1), rational(0)], [rational(-1), rational(0), rational(0)], [rational(2), rational(0), rational(1)]])))).toBe('Point2D(1, 1)');
  });
  it("Point(0, 0).transform(rot_about_11)", () => {
    expect(sympyStr(Point2D(rational(0), rational(0), { evaluate: false }).transform(Matrix.of([[rational(0), rational(1), rational(0)], [rational(-1), rational(0), rational(0)], [rational(2), rational(0), rational(1)]])))).toBe('Point2D(2, 0)');
  });
  it("rpent", () => {
    expect(sympyStr(RegularPolygon(Point2D(rational(1), rational(2), { evaluate: false }), rational(1), rational(5), rational(0)).reflect(Line2D(Point2D(rational(0), pi, { evaluate: false }), Point2D(rational(1), add(pi, pow(2, rational(1, 2))), { evaluate: false }))))).toBe('RegularPolygon(Point2D(-2*sqrt(2)*pi/3 - 1/3 + 4*sqrt(2)/3, 2/3 + 2*sqrt(2)/3 + 2*pi/3), -1, 5, -atan(2*sqrt(2)) + 3*pi/5)');
  });
  it("rcirc", () => {
    expect(sympyStr(Circle(Point2D(rational(0), rational(0), { evaluate: false }), rational(5)).reflect(Line2D(Point2D(rational(0), pi, { evaluate: false }), Point2D(rational(1), add(1, pi), { evaluate: false }))))).toBe('Circle(Point2D(-pi, pi), -5)');
  });
});

